const $=id=>document.getElementById(id);let stream=null,sharing=null,micOn=true,camOn=false,inRoom=false,timer=null,started=0,audioContext=null;const fields=$('deviceFields');
function setStatus(text){$('deviceStatus').textContent=text;$('roomStatus').textContent=text;$('settingsStatus').textContent=text}
function openSettings(){$('settingsFields').append(fields);$('settings').showModal()}$('settingsOpen').onclick=openSettings;$('settings').addEventListener('close',()=>{$('joinForm').insertBefore(fields,$('fieldsAnchor'))});
$('joinForm').onsubmit=e=>{e.preventDefault();const name=$('name').value.trim();if(!name){$('name').setCustomValidity('Please enter your name.');$('name').reportValidity();return}$('entrance').hidden=true;$('room').hidden=false;inRoom=true;$('selfName').textContent=name+' · You';$('selfInitial').textContent=name[0].toUpperCase();started=Date.now();timer=setInterval(()=>{$('timer').textContent=new Date(Date.now()-started).toISOString().slice(11,19)},1000);sync();window.scrollTo(0,0)};$('name').oninput=()=> $('name').setCustomValidity('');
function chat(open){$('chatPanel').hidden=!open;document.querySelector('.meeting-layout').classList.toggle('chat-closed',!open)}$('chatToggle').onclick=()=>chat($('chatPanel').hidden);$('closeChat').onclick=()=>chat(false);
$('chatForm').onsubmit=e=>{e.preventDefault();const text=$('chatInput').value.trim();if(!text)return;const div=document.createElement('div');div.className='message';const strong=document.createElement('strong');strong.textContent=$('name').value.trim()+' · You';const p=document.createElement('p');p.textContent=text;div.append(strong,p);$('messages').append(div);$('chatInput').value='';div.scrollIntoView({block:'nearest'})};
$('handToggle').onclick=()=>{const raised=$('handToggle').getAttribute('aria-pressed')!=='true';$('handToggle').setAttribute('aria-pressed',raised);$('handToggle').lastElementChild.textContent=raised?'Lower hand':'Raise hand';$('handBadge').hidden=!raised};
$('viewToggle').onclick=()=>{const speaker=$('gallery').classList.toggle('speaker');$('viewToggle').textContent=speaker?'▦  Gallery view':'▦  Speaker view'};
$('peopleOpen').onclick=()=>{$('peopleList').replaceChildren();[$('name').value.trim()+' · You','Angela · Demo','Michelle · Demo','Denise · Demo'].forEach(name=>{const li=document.createElement('li');li.textContent=name;$('peopleList').append(li)});$('people').showModal()};
function stopShare(){sharing?.getTracks().forEach(t=>t.stop());sharing=null;$('sharePreview').srcObject=null;$('sharePreview').hidden=true;$('sharePreview').classList.remove('active');$('shareToggle').lastElementChild.textContent='Share screen'}
$('shareToggle').onclick=async()=>{if(sharing)return stopShare();if(!navigator.mediaDevices?.getDisplayMedia)return setStatus('Screen sharing is unavailable in this browser.');try{sharing=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});$('sharePreview').srcObject=sharing;$('sharePreview').hidden=false;$('sharePreview').classList.add('active');$('shareToggle').lastElementChild.textContent='Stop sharing';sharing.getVideoTracks()[0].onended=stopShare;setStatus('Local screen preview only. Live sharing will be available when video calling is connected.')}catch{setStatus('Screen sharing was cancelled or unavailable.')}};
$('leave').onclick=()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;camOn=false;micOn=false;stopMeter();stopShare();clearInterval(timer);inRoom=false;$('room').hidden=true;$('entrance').hidden=false;$('timer').textContent='00:00:00';sync();setStatus('You’ve left the demo gathering. Your camera and microphone have been released.');window.scrollTo(0,0)};window.addEventListener('pagehide',()=>{stream?.getTracks().forEach(t=>t.stop());sharing?.getTracks().forEach(t=>t.stop())});devices().catch(()=>{});sync();
